import { ZOOM_TYPE } from '../constants';
export function selectionToZoomBounds(args) {
    const { selection, xAxis, xScale, yAxes, yScales, zoomType } = args;
    const zoomState = {};
    switch (zoomType) {
        case ZOOM_TYPE.X: {
            const [x0, x1] = selection;
            zoomState.x = selectionXToZoomBounds({ xAxis, xScale, selection: [x0, x1] });
            break;
        }
        case ZOOM_TYPE.Y: {
            const [y1, y0] = selection;
            yAxes.forEach((yAxis, index) => {
                if (!Array.isArray(zoomState.y)) {
                    zoomState.y = [];
                }
                const yScale = yScales[index];
                if (yScale) {
                    zoomState.y.push(selectionYToZoomBounds({
                        yAxis,
                        yScale,
                        selection: [y1, y0],
                    }));
                }
                else {
                    zoomState.y.push(undefined);
                }
            });
            break;
        }
        case ZOOM_TYPE.XY: {
            const [x0, y0] = selection[0];
            const [x1, y1] = selection[1];
            zoomState.x = selectionXToZoomBounds({ xAxis, xScale, selection: [x0, x1] });
            yAxes.forEach((yAxis, index) => {
                if (!Array.isArray(zoomState.y)) {
                    zoomState.y = [];
                }
                const yScale = yScales[index];
                if (yScale) {
                    zoomState.y.push(selectionYToZoomBounds({
                        yAxis,
                        yScale,
                        selection: [y0, y1],
                    }));
                }
                else {
                    zoomState.y.push(undefined);
                }
            });
            break;
        }
    }
    return zoomState;
}
function selectionXToZoomBounds(args) {
    const { xAxis, xScale, selection } = args;
    switch (xAxis.type) {
        case 'category': {
            const [x0, x1] = selection;
            const bandScale = xScale;
            const categories = xAxis.categories || [];
            const currentDomain = bandScale.domain();
            const step = bandScale.step();
            let startIndex = Math.floor(x0 / step);
            let endIndex = Math.floor(x1 / step);
            const startCategory = currentDomain[startIndex];
            const endCategory = currentDomain[endIndex];
            startIndex = categories.indexOf(startCategory);
            endIndex = categories.indexOf(endCategory);
            if (!categories[startIndex]) {
                startIndex = 0;
            }
            if (!categories[endIndex]) {
                endIndex = categories.length - 1;
            }
            return [startIndex, endIndex];
        }
        case 'datetime': {
            const [x0, x1] = selection;
            const timeScale = xScale;
            const minTimestamp = timeScale.invert(x0).getTime();
            const maxTimestamp = timeScale.invert(x1).getTime();
            return [minTimestamp, maxTimestamp];
        }
        case 'linear':
        case 'logarithmic': {
            const [x0, x1] = selection;
            const linearScale = xScale;
            const minValue = linearScale.invert(x0);
            const maxValue = linearScale.invert(x1);
            return [minValue, maxValue];
        }
        default: {
            throw new Error(`Invalid axis type: ${xAxis.type}`);
        }
    }
}
function getYMinMaxFromSelection(args) {
    const { selection, yAxis } = args;
    let yMin;
    let yMax;
    switch (yAxis.order) {
        case 'reverse':
        case 'sortDesc': {
            [yMin, yMax] = selection;
            break;
        }
        default: {
            [yMax, yMin] = selection;
        }
    }
    return [yMin, yMax];
}
function selectionYToZoomBounds(args) {
    const { yAxis, yScale, selection } = args;
    switch (yAxis.type) {
        case 'category': {
            const [y1, y0] = selection;
            const bandScale = yScale;
            const categories = yAxis.categories || [];
            const currentDomain = bandScale.domain();
            const step = bandScale.step();
            let startIndex = Math.max(0, currentDomain.length - 1 - Math.floor(y0 / step));
            let endIndex = Math.min(currentDomain.length - 1, currentDomain.length - 1 - Math.floor(y1 / step));
            const startCategory = currentDomain[startIndex];
            const endCategory = currentDomain[endIndex];
            startIndex = categories.indexOf(startCategory);
            endIndex = categories.indexOf(endCategory);
            if (!categories[startIndex]) {
                startIndex = 0;
            }
            if (!categories[endIndex]) {
                endIndex = categories.length - 1;
            }
            return [startIndex, endIndex];
        }
        case 'datetime': {
            const [yMin, yMax] = getYMinMaxFromSelection({ selection, yAxis });
            const timeScale = yScale;
            const minTimestamp = timeScale.invert(yMin).getTime();
            const maxTimestamp = timeScale.invert(yMax).getTime();
            return [minTimestamp, maxTimestamp];
        }
        case 'linear':
        case 'logarithmic': {
            const [yMin, yMax] = getYMinMaxFromSelection({ selection, yAxis });
            const linearScale = yScale;
            const minValue = linearScale.invert(yMin);
            const maxValue = linearScale.invert(yMax);
            return [minValue, maxValue];
        }
        default: {
            throw new Error(`Invalid axis type: ${yAxis.type}`);
        }
    }
}
